WITH filtered_payments AS (SELECT * FROM payments WHERE method IN ('cash', 'paypal', 'card')), payments_stats AS (SELECT DATE_TRUNC('MONTH', paid_at) AS paid_month, MAX(paid_at) AS latest_paid_at, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM filtered_payments GROUP BY DATE_TRUNC('MONTH', paid_at)) SELECT paid_month, latest_paid_at, status_values FROM payments_stats
